# Writes src/text/Cp932Table.inc: the code points of the Shift-JIS (code page 932) byte pairs,
# from Python's cp932 codec (Microsoft's table, the one .NET's code page 932 decodes with).
#   python gen_cp932.py <out.inc>
import sys

LEADS = list(range(0x81, 0xA0)) + list(range(0xE0, 0xFD))
TRAILS = range(0x40, 0xFD)

def decode(raw):
    try:
        text = raw.decode("cp932")
    except UnicodeDecodeError:
        return 0
    return ord(text) if len(text) == 1 else 0

def main():
    out = sys.argv[1]
    lines = [
        "// Generated by tools/gen_cp932.py: do not edit.",
        "// kSingle[b]: the code point of byte b alone (0 for a lead byte or none);",
        "// kDouble[lead index][trail - 0x40]: of a pair (0 for none).",
        "static const uint16_t kSingle[256] = {",
    ]
    single = [0 if b in LEADS else decode(bytes([b])) for b in range(256)]
    for i in range(0, 256, 16):
        lines.append("    " + ", ".join(f"0x{v:04X}" for v in single[i:i + 16]) + ",")
    lines.append("};")
    lines.append(f"static const uint16_t kDouble[{len(LEADS)}][{len(TRAILS)}] = {{")
    for lead in LEADS:
        row = [decode(bytes([lead, t])) for t in TRAILS]
        lines.append("    {")
        for i in range(0, len(row), 16):
            lines.append("        " + ", ".join(f"0x{v:04X}" for v in row[i:i + 16]) + ",")
        lines.append("    },")
    lines.append("};")
    with open(out, "w", encoding="ascii", newline="\n") as f:
        f.write("\n".join(lines) + "\n")

if __name__ == "__main__":
    main()
